<script setup lang="ts">
import { computed, reactive, ref, watch } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { teacherDelete, teacherGet, teacherPost, teacherPut, type TeacherClass, type TeacherStudent, type TeacherSubmission } from "../../../teacher/teacherApi";
import { languageLabel, monacoLanguage } from "../../../data/languages";
import { formatDisplayDateTime } from "../../../lib/format";
import CodeEditor from "../../components/CodeEditor.vue";

type BatchAction="ASSIGN_CLASS"|"REMOVE_CLASS"|"RESET_PASSWORD"|"RESET_AI_QUOTA"|"DELETE";
type Quota={used:number;remaining:number};type StudentDetail={id:number;username?:string;displayName?:string;avatarUrl?:string;studentNo?:string;email?:string;role?:string;className?:string;createdAt?:string;updatedAt?:string};type Page<T>={list:T[];total:number};
const batchLabels:Record<BatchAction,string>={ASSIGN_CLASS:"调整班级",REMOVE_CLASS:"移出班级",RESET_PASSWORD:"重置密码",RESET_AI_QUOTA:"重置 AI 额度",DELETE:"删除学生"};
const rows=ref<TeacherStudent[]>([]);const classes=ref<TeacherClass[]>([]);const quotas=ref<Record<number,Quota>>({});const loading=ref(false);const keyword=ref("");const classFilter=ref<number|null>(null);const quotaFilter=ref<"all"|"has"|"none">("all");const page=ref(1);const pageSize=ref(20);const selectedIds=ref<number[]>([]);
const batchAction=ref<BatchAction|null>(null);const batchDialog=ref(false);const batchClassId=ref<number|undefined>();const batchPassword=ref("");const batchBusy=ref(false);const editStudent=ref<TeacherStudent|null>(null);const editBusy=ref(false);const editForm=reactive({displayName:"",studentNo:"",email:"",password:""});
const detailVisible=ref(false);const detailLoading=ref(false);const detail=ref<StudentDetail|null>(null);const submissions=ref<TeacherSubmission[]>([]);const submissionPage=ref(1);const submissionTotal=ref(0);const submissionLoading=ref(false);const codeDialog=ref(false);const codeLoading=ref(false);const code=ref("");const codeLang=ref("plaintext");
const filtered=computed(()=>rows.value.filter(student=>{const q=keyword.value.trim().toLocaleLowerCase();if(q&&![student.displayName,student.username,student.email,student.studentNo].some(value=>value?.toLocaleLowerCase().includes(q)))return false;if(classFilter.value!=null&&student.classId!==classFilter.value)return false;if(quotaFilter.value!=="all"){const quota=quotas.value[student.userId];if(!quota||(quotaFilter.value==="has"?quota.remaining<=0:quota.remaining>0))return false;}return true;}));
const pageRows=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
const selectedRows=computed(()=>selectedIds.value.map(id=>rows.value.find(student=>student.userId===id)).filter((student):student is TeacherStudent=>Boolean(student)));
function rowSelectionChanged(selection:TeacherStudent[]){const currentPageIds=pageRows.value.map(student=>student.userId);const outside=selectedIds.value.filter(id=>!currentPageIds.includes(id));const next=[...outside,...selection.map(student=>student.userId)];if(next.length>500){ElMessage.warning("一次最多选择 500 名学生");return;}selectedIds.value=Array.from(new Set(next));}
async function load(){loading.value=true;try{const [studentRows,classRows]=await Promise.all([teacherGet<TeacherStudent[]>("/api/teacher/v1/students"),teacherGet<TeacherClass[]>("/api/teacher/v1/classes")]);rows.value=studentRows;classes.value=classRows;selectedIds.value=selectedIds.value.filter(id=>studentRows.some(row=>row.userId===id));const chunks=Array.from({length:Math.ceil(studentRows.length/100)},(_,i)=>studentRows.slice(i*100,(i+1)*100));const results=await Promise.all(chunks.map(chunk=>teacherGet<Record<number,Quota>>(`/api/teacher/v1/students/quotas?userIds=${chunk.map(student=>student.userId).join(",")}`)));quotas.value=Object.assign({},...results);}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"学生列表加载失败");}finally{loading.value=false;}}
function resetFilters(){keyword.value="";classFilter.value=null;quotaFilter.value="all";page.value=1;selectedIds.value=[];}
function openBatch(action:BatchAction){batchAction.value=action;batchClassId.value=undefined;batchPassword.value="";batchDialog.value=true;}
async function submitBatch(){const action=batchAction.value;if(!action||!selectedIds.value.length)return;if(action==="ASSIGN_CLASS"&&!batchClassId.value){ElMessage.warning("请选择目标班级");return;}if(action==="RESET_PASSWORD"){const password=batchPassword.value.trim();if(password.length<6||new TextEncoder().encode(password).length>72){ElMessage.warning("新密码至少 6 个字符，最多 72 字节");return;}}if(action==="DELETE"){try{await ElMessageBox.confirm(`将永久删除所选的 ${selectedIds.value.length} 名学生账号及其关联记录。`,"删除学生",{type:"warning"});}catch{return;}}
  batchBusy.value=true;try{const result=await teacherPost<{affectedCount:number}>("/api/teacher/v1/students/batch",{action,userIds:selectedIds.value,classId:action==="ASSIGN_CLASS"?batchClassId.value:undefined,password:action==="RESET_PASSWORD"?batchPassword.value.trim():undefined},300000);ElMessage.success(`${batchLabels[action]}成功，共 ${result.affectedCount} 名学生`);batchAction.value=null;batchDialog.value=false;selectedIds.value=[];await load();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"批量操作失败");}finally{batchBusy.value=false;}}
function openEdit(student:TeacherStudent){editStudent.value=student;Object.assign(editForm,{displayName:student.displayName??"",studentNo:student.studentNo??"",email:student.email??"",password:""});}
async function saveEdit(){if(!editStudent.value)return;const body:Record<string,string>={};if(editForm.displayName.trim())body.displayName=editForm.displayName.trim();if(editForm.studentNo.trim())body.studentNo=editForm.studentNo.trim();if(editForm.email.trim())body.email=editForm.email.trim();if(editForm.password.trim()){if(editForm.password.trim().length<6){ElMessage.warning("密码至少 6 个字符");return;}body.password=editForm.password.trim();}editBusy.value=true;try{await teacherPut(`/api/teacher/v1/students/${editStudent.value.userId}`,body);ElMessage.success("学生信息已更新");editStudent.value=null;await load();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"学生信息更新失败");}finally{editBusy.value=false;}}
async function removeStudent(student:TeacherStudent){if(!student.classId)return;try{await ElMessageBox.confirm(`从班级移除 ${student.displayName||student.username||student.userId}？账号和历史提交会保留。`,"移出班级",{type:"warning"});await teacherDelete(`/api/teacher/v1/classes/${student.classId}/students/${student.userId}`);ElMessage.success("学生已从班级移除");await load();}catch(cause){if(cause!=="cancel"&&cause!=="close")ElMessage.error(cause instanceof Error?cause.message:"移除失败");}}
async function loadSubmissions(userId:number,nextPage=1){submissionLoading.value=true;submissionPage.value=nextPage;try{const result=await teacherGet<Page<TeacherSubmission>>(`/api/teacher/v1/submissions?page=${nextPage}&pageSize=10&userId=${userId}&sortBy=submitTime&sortOrder=desc`);submissions.value=result.list??[];submissionTotal.value=result.total??0;}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"最近提交加载失败");}finally{submissionLoading.value=false;}}
async function openDetail(student:TeacherStudent){detailVisible.value=true;detailLoading.value=true;detail.value={id:student.userId,username:student.username??undefined,displayName:student.displayName??undefined,studentNo:student.studentNo??undefined,email:student.email??undefined,className:student.className??undefined};void loadSubmissions(student.userId,1);try{detail.value=await teacherGet<StudentDetail>(`/api/teacher/v1/students/${student.userId}`);}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"学生详情加载失败");}finally{detailLoading.value=false;}}
async function viewCode(submission:TeacherSubmission){codeDialog.value=true;codeLoading.value=true;code.value="";codeLang.value=monacoLanguage(submission.language);try{code.value=await teacherGet<string>(`/api/teacher/v1/submissions/${submission.id}/code`);}catch(cause){code.value=cause instanceof Error?cause.message:"代码加载失败";}finally{codeLoading.value=false;}}
function statusType(status?:string){if(status==="AC"||status==="ACCEPTED")return"success";if(["WA","RE","WRONG_ANSWER","RUNTIME_ERROR"].includes(status??""))return"danger";if(["TLE","MLE"].includes(status??""))return"warning";return"info";}
watch(()=>[keyword.value,classFilter.value,quotaFilter.value] as const,()=>{page.value=1;selectedIds.value=[];});
void load();
</script>

<template><section class="students-page page-container"><el-card shadow="never"><div class="filters"><el-input v-model="keyword" clearable placeholder="用户名、姓名、邮箱或学号"/><el-select v-model="classFilter" clearable placeholder="筛选班级"><el-option v-for="room in classes" :key="room.id" :value="room.id" :label="room.name"/></el-select><el-select v-model="quotaFilter"><el-option label="全部 AI 额度" value="all"/><el-option label="有剩余额度" value="has"/><el-option label="无剩余额度" value="none"/></el-select><el-button @click="resetFilters">重置筛选</el-button></div><div class="batch-toolbar"><span>已选择 {{selectedIds.length}} 名学生（可跨页选择，最多 500 名）</span><div class="batch-buttons"><el-button v-for="action in (Object.keys(batchLabels) as BatchAction[])" :key="action" :type="action==='DELETE'?'danger':'default'" :disabled="!selectedIds.length||batchBusy" @click="openBatch(action)">批量{{batchLabels[action]}}</el-button><el-button :disabled="!selectedIds.length" @click="selectedIds=[]">清空选择</el-button></div></div><el-table v-loading="loading" :data="pageRows" stripe row-key="userId" @selection-change="rowSelectionChanged"><el-table-column type="selection" width="48"/><el-table-column prop="userId" label="用户 ID" width="90"/><el-table-column prop="username" label="用户名" min-width="120"/><el-table-column prop="displayName" label="姓名" min-width="110"/><el-table-column prop="className" label="班级" min-width="130"><template #default="{row}">{{row.className||'-'}}</template></el-table-column><el-table-column prop="studentNo" label="学号" min-width="120"><template #default="{row}">{{row.studentNo||'-'}}</template></el-table-column><el-table-column prop="email" label="邮箱" min-width="170"><template #default="{row}">{{row.email||'-'}}</template></el-table-column><el-table-column label="最后提交" min-width="160"><template #default="{row}">{{row.lastSubmissionTime?formatDisplayDateTime(row.lastSubmissionTime):'未提交'}}</template></el-table-column><el-table-column label="AI 额度" width="110"><template #default="{row}"><el-tag v-if="quotas[row.userId]" :type="quotas[row.userId].remaining>0?'success':'danger'">{{quotas[row.userId].remaining}} / {{quotas[row.userId].remaining+quotas[row.userId].used}}</el-tag><span v-else>-</span></template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDetail(row)">查看</el-button><el-button link @click="openEdit(row)">编辑</el-button><el-button link type="danger" @click="removeStudent(row)">移出班级</el-button></template></el-table-column></el-table><div class="pagination"><Pagination v-model:page="page" v-model:limit="pageSize" :page-sizes="[20,50,100]" :total="filtered.length"/></div></el-card>
  <el-dialog class="qoj-management-dialog" v-model="batchDialog" :title="batchAction?`批量${batchLabels[batchAction]}`:'批量管理学生'" width="560px"><p>本次操作已选择 {{selectedIds.length}} 名学生。</p><p class="muted">{{selectedRows.map(student=>student.displayName||student.username||`#${student.userId}`).join('、')}}</p><el-alert v-if="batchAction==='ASSIGN_CLASS'" type="info" :closable="false" title="仅可转入自己的班级；旧班级课程权限撤销，历史提交保留。"/><el-select v-if="batchAction==='ASSIGN_CLASS'" v-model="batchClassId" placeholder="选择目标班级" class="full-width"><el-option v-for="room in classes" :key="room.id" :value="room.id" :label="room.name"/></el-select><el-alert v-if="batchAction==='REMOVE_CLASS'" type="warning" :closable="false" title="学生将不再显示在您的学生列表中；账号和历史提交保留。"/><el-input v-if="batchAction==='RESET_PASSWORD'" v-model="batchPassword" type="password" show-password maxlength="72" placeholder="统一新密码（至少 6 个字符）"/><el-alert v-if="batchAction==='RESET_AI_QUOTA'" type="info" :closable="false" title="仅重置所选学生今天已使用的 AI 额度。"/><el-alert v-if="batchAction==='DELETE'" type="error" :closable="false" title="将永久删除所选学生账号及关联记录。"/><template #footer><el-button :disabled="batchBusy" @click="batchDialog=false;batchAction=null">取消</el-button><el-button type="primary" :loading="batchBusy" @click="submitBatch">确认执行</el-button></template></el-dialog>
  <el-dialog class="qoj-management-dialog" :model-value="Boolean(editStudent)" title="编辑学生" width="520px" @close="editStudent=null"><el-form label-position="top"><el-form-item label="姓名"><el-input v-model="editForm.displayName" placeholder="留空不修改" maxlength="50"/></el-form-item><el-form-item label="学号"><el-input v-model="editForm.studentNo" placeholder="留空不修改" maxlength="50"/></el-form-item><el-form-item label="邮箱"><el-input v-model="editForm.email" placeholder="留空不修改" maxlength="100"/></el-form-item><el-form-item label="密码"><el-input v-model="editForm.password" type="password" show-password placeholder="留空不修改密码"/></el-form-item></el-form><template #footer><el-button @click="editStudent=null">取消</el-button><el-button type="primary" :loading="editBusy" @click="saveEdit">保存</el-button></template></el-dialog>
  <el-dialog class="qoj-management-dialog" v-model="detailVisible" title="学生详情" width="min(1000px,94vw)"><el-card v-loading="detailLoading" shadow="never"><template #header>个人信息</template><el-descriptions v-if="detail" :column="2" border><el-descriptions-item label="ID">{{detail.id}}</el-descriptions-item><el-descriptions-item label="用户名">{{detail.username||'-'}}</el-descriptions-item><el-descriptions-item label="姓名">{{detail.displayName||'-'}}</el-descriptions-item><el-descriptions-item label="角色">{{detail.role||'学生'}}</el-descriptions-item><el-descriptions-item label="学号">{{detail.studentNo||'-'}}</el-descriptions-item><el-descriptions-item label="邮箱">{{detail.email||'-'}}</el-descriptions-item><el-descriptions-item label="班级">{{detail.className||'-'}}</el-descriptions-item><el-descriptions-item label="AI 额度">{{quotas[detail.id]?`${quotas[detail.id].remaining}/${quotas[detail.id].remaining+quotas[detail.id].used}`:'-'}}</el-descriptions-item><el-descriptions-item label="创建时间">{{detail.createdAt?formatDisplayDateTime(detail.createdAt):'-'}}</el-descriptions-item></el-descriptions></el-card><el-card shadow="never" class="submission-card"><template #header>最近提交记录</template><el-table v-loading="submissionLoading" :data="submissions" stripe><el-table-column prop="id" label="提交 ID" width="95"/><el-table-column prop="problemTitle" label="题目" min-width="180"/><el-table-column prop="language" label="语言" width="100"><template #default="{row}">{{languageLabel(row.language)}}</template></el-table-column><el-table-column prop="status" label="状态" width="110"><template #default="{row}"><el-tag :type="statusType(row.status)">{{row.status}}</el-tag></template></el-table-column><el-table-column prop="score" label="分数" width="80"/><el-table-column prop="submitTime" label="提交时间" min-width="170"><template #default="{row}">{{row.submitTime?formatDisplayDateTime(row.submitTime):'-'}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="viewCode(row)">查看代码</el-button></template></el-table-column></el-table><Pagination class="right-pagination" :page="submissionPage" :limit="10" :total="submissionTotal" @pagination="({ page }) => loadSubmissions(detail!.id,page)"/></el-card></el-dialog>
  <el-dialog class="qoj-management-dialog" v-model="codeDialog" title="提交代码" width="min(1000px,92vw)"><el-skeleton v-if="codeLoading" :rows="8" animated/><div v-else class="code-editor"><CodeEditor v-model="code" :language="codeLang" read-only/></div></el-dialog>
</section></template>

<style scoped>.students-page{display:flex;flex-direction:column;gap:16px}.page-heading,.filters,.batch-toolbar,.batch-buttons,.pagination{display:flex;align-items:center;gap:10px}.page-heading,.batch-toolbar,.pagination{justify-content:space-between}.page-heading h1{margin:0;font-size:22px}.page-heading p,.muted{margin:6px 0 0;color:var(--el-text-color-secondary);font-size:13px}.filters{flex-wrap:wrap;margin-bottom:14px}.filters>*{width:200px}.batch-toolbar{margin-bottom:12px;color:var(--el-text-color-secondary);font-size:13px}.batch-buttons{flex-wrap:wrap;justify-content:flex-end}.pagination{margin-top:14px}.full-width{width:100%;margin-top:12px}.submission-card{margin-top:14px}.right-pagination{justify-content:flex-end;margin-top:12px}.code-editor{height:60vh;min-height:360px}@media(max-width:800px){.page-heading,.batch-toolbar,.pagination{align-items:flex-start;flex-direction:column}.batch-buttons{justify-content:flex-start}.filters>*{flex:1;min-width:150px}}</style>
